-- Owner 2026-11-05: "ORM ทำเลย" — ORM (Thai Metal Aluminium) as an extruder. No weights or bar length printed anywhere; priced PER BAR from the ORM retail price book Ver.3 2025/4 (23/10/2025, incl. VAT), one variant per die x thickness x colour at an assumed 6.4 m bar. Weights 0 (red ไม่มีน้ำหนัก badge) until ORM gives weights.
-- Parts: docs/catalogs/orm/orm-2025.json. Generated by 2026-11-05-import-orm.gen.py + .config.json; refuses to run twice.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM alu_providers WHERE tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND (id = '528864e7-80be-5a27-8560-4b1f2f588bb5' OR short_name = 'ORM')) THEN RAISE EXCEPTION 'already imported'; END IF; END $$;
DO $$ DECLARE a int; b int; c int; f int; e int; BEGIN
  SELECT count(*) INTO a FROM alu_series WHERE provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5';
  SELECT count(*) INTO b FROM alu_profiles WHERE provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5';
  SELECT count(*) INTO c FROM alu_series_profiles sp JOIN alu_series s ON s.id = sp.series_id WHERE s.provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5';
  SELECT count(*) INTO f FROM alu_profiles WHERE provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5' AND image_path IS NOT NULL;
  SELECT count(*) INTO e FROM alu_profile_variants v JOIN alu_profiles ap ON ap.id = v.profile_id WHERE ap.provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5';
  IF a <> 13 OR b <> 223 OR c <> 224 OR f <> 223 OR e <> 1114 THEN
    RAISE EXCEPTION 'count mismatch: series % profiles % links % images % prices %', a, b, c, f, e; END IF;
END $$;
SELECT f.name family, s.name series, count(sp.id) profiles, (SELECT count(*) FROM alu_series_types st WHERE st.series_id = s.id) types FROM alu_series s JOIN alu_series_families f ON f.id = s.series_family_id LEFT JOIN alu_series_profiles sp ON sp.series_id = s.id WHERE s.provider_id = '528864e7-80be-5a27-8560-4b1f2f588bb5' GROUP BY f.name, f.sort_order, s.id, s.name ORDER BY f.sort_order, s.name;
COMMIT;
